namespace Autheris.Application.Security.Totp.Interfaces;

using System.Threading;
using System.Threading.Tasks;
using Autheris.Domain.Model;

public enum TotpEnrollmentOutcome
{
    Completed,
    NoPendingEnrollment,
    InvalidCode,
    CurrentCodeRequired,
    InvalidCurrentCode,
    StoreUnavailable
}

/// <summary>
/// SR-M-01: server-side TOTP enrollment. The seed is generated by the server and held as a pending, user-bound,
/// short-lived value; completing the enrollment only ever accepts a code for that pending seed (never a client seed),
/// and replacing an active secret additionally requires a valid code from the CURRENT secret.
/// </summary>
public interface ITotpEnrollmentService
{
    /// <summary>Generates a seed and stores it as pending for the user. Returns null when no pending store is usable (fail closed).</summary>
    Task<TotpEnrollmentResult?> BeginEnrollmentAsync(string userSid, string email, string issuer, CancellationToken ct = default);

    Task<bool> HasActiveSecretAsync(string userSid, CancellationToken ct = default);

    Task<TotpEnrollmentOutcome> CompleteEnrollmentAsync(string userSid, string totpCode, string? currentTotpCode, CancellationToken ct = default);
}
